import { FormControl } from "@angular/forms";

/**
 * Interface representing a structured field in a form.
 */
export interface StructureFieldForm {
  /** Name of the field. */
  name: FormControl<string | null>;
  /** Type of the field. */
  type: FormControl<string | null>;
  /** Is the field required. */
  required: FormControl<boolean | null>;
  /** Is the field part of an array. */
  array: FormControl<boolean | null>;
  /** Is the field generated by the product. */
  generated: FormControl<boolean | null>;
  /** Is the field not modifiable after creation. */
  notModifiable: FormControl<boolean | null>;
}